# Daily research run 2026-11-13: Nathan Tufts (cordwainer), Deacon Amos Tufts, and the Tufts mill on the Medford Turnpike.
_SAWIA = '<a href="https://archive.org/details/oldcharlestownhi1902sawy">Internet Archive</a>'
def _SW(p): return f'Timothy T. Sawyer, <em>Old Charlestown: Historical, Biographical, Reminiscent</em> (Boston, 1902), p. {p}. {_SAWIA}'
_M20 = '<em>Medford Historical Register</em>, vol. XXIII, no. 1 (March 1920), &ldquo;The Mills on the Medford Turnpike,&rdquo; pp. 20&ndash;21. <a href="https://archive.org/details/medfordhistorica36medf">Internet Archive</a>'
IMAGES['gershom-cutter-house-medford-turnpike.jpg'] = ('House of Gershom Cutter, proprietor of the mill on the Medford Turnpike', 'Plate from the Medford Historical Register&rsquo;s 1920 &ldquo;Turnpike Number.&rdquo; Cutter bought the Tufts mill on the turnpike in 1845; the Register says his house stood on the opposite side of the road from the mill site.', '<em>Medford Historical Register</em>, vol. XXIII, no. 1 (March 1920), frontispiece', 'Public domain (published 1920)', 'https://archive.org/details/medfordhistorica36medf/page/n13', 'Internet Archive')
_NC = "nathan-tufts-cordwainer"; _AM = "amos-tufts-1762"
PROFILES.append(dict(slug=_NC, name="Nathan Tufts, Cordwainer, of Medford", dates="[dates not confirmed]", town="Medford, Mass.", born="", died="", era="The Revolution",
  line="Son of Peter Tufts of Milk Row; father of Daniel, Deacon Amos, and Nathan Tufts of Charlestown",
  bio=('<p>Nathan Tufts was a shoemaker by trade who made his living mostly by farming in Medford. He was a son of Peter Tufts of the Milk Row road in Charlestown (now Somerville), and his three sons became leading business men of Charlestown: a brick-maker, a blacksmith, and a butcher, tanner and mill owner.</p>'
    + Q("One of the sons of this Peter was Nathan Tufts, by trade a cordwainer, but chiefly occupied as a farmer in Medford. He was the father of Daniel, Deacon Amos, and Nathan Tufts, who for the greater part of their lives were prominent citizens of the old town and among its leading business men.", _SW(162))
    + '<p>His sons on this site are ' + PL(_AM, "Deacon Amos Tufts (c. 1762&ndash;1839)") + ' and ' + PL("nathan-tufts-1764", "Nathan Tufts of Charlestown (c. 1764&ndash;1835)") + '. Sawyer describes the eldest, Daniel, as a brick-maker and farmer who lived outside Charlestown Neck and sat in the Legislature in 1811 and 1812 (p. 162).</p>'),
  service='<p>No military service has yet been matched to him with confidence. Note: Pending further work.</p>',
  family=('<p>Father: Peter Tufts of Milk Row, carpenter and farmer (Sawyer, p. 162). Wife: Mary Adams, as named in the Adams genealogy (p. 974) as the mother of his sons Amos and Nathan. Sons: Daniel (brick-maker, of Charlestown), ' + PL(_AM, "Deacon Amos") + ', and ' + PL("nathan-tufts-1764", "Nathan") + '.</p>'),
  unverified='<strong>Dates and identity:</strong> Sawyer gives no dates for him. He may be the same man as ' + PL("nathan-tufts-15-7", "Nathan Tufts (1741&ndash;1784)") + ' of Medford, whose parents are not named in the source used for that page, but this is not established. <strong>Daniel, his son:</strong> whether he is the ' + PL("daniel-tufts", "Daniel Tufts") + ' of the Medford Lexington-alarm roll is not established. Note: Pending further work.'))
SP[_NC] = "<ul><li><strong>Mary (Adams) Tufts</strong>, per the Adams genealogy, p. 974, as cited on the pages of her grandsons. Marriage date not found.</li></ul>"
NEWUNCHK.add(_NC)
REL[_NC] = [(_AM, "son Deacon Amos Tufts (c. 1762&ndash;1839)"), ("nathan-tufts-1764", "son Nathan Tufts of Charlestown (c. 1764&ndash;1835)"), ("william-tufts-1802", "grandson William Tufts"), ("edward-tufts-1806", "grandson Edward Tufts")]
PROFILES.append(dict(slug=_AM, name="Deacon Amos Tufts (c. 1762&ndash;1839)", dates="c. 1762&ndash;26 November 1839", town="Charlestown, Mass.", born="1762", died="1839", era="19th Century",
  line="Son of Nathan Tufts, cordwainer of Medford; blacksmith and deacon of the First Church, Charlestown",
  bio=('<p>Amos Tufts was a Charlestown blacksmith and, for some years, the leading layman of the First Church. He was a son of ' + PL(_NC, "Nathan Tufts, the Medford cordwainer and farmer") + ', and a brother of ' + PL("nathan-tufts-1764", "Nathan Tufts of Charlestown") + '.</p>'
    + Q("Deacon Amos Tufts lived on the corner of Main and Bow streets, in a house built about 1800. The lot of land on which it stood was formerly a part of the estate of Isaiah Edes, who sold it to N. Trask, and he to Amos Tufts in 1796.", _SW(165))
    + '<p>Sawyer describes the house as wooden and &ldquo;oblong-square,&rdquo; one end on Main Street and the broadside on Bow Street, with its front door looking up Middlegate Street toward Town Hill. He lived there until his death on November 26, 1839, at seventy-seven (p. 165).</p>'
    + Q("He carried on an extensive business, for his time, as a blacksmith. His shop was in the rear of his house on Main Street, and the area between the two buildings was always a scene of industry. The shop was a brick building, three stories high, erected with the view of alteration at some time into a dwelling-house, which was afterwards done.", _SW("165&ndash;166"))
    + '<p>His eldest son, Joseph F. Tufts, worked early for his uncle Nathan in the tanning business, was later a partner of Gilbert Tufts in a tannery on Main Street near the Neck, and served as treasurer of the Warren Institution for Savings. One of his daughters married Deacon Eliab P. Mackintire, a Charlestown dry-goods merchant and legislator (Sawyer, pp. 166&ndash;167). His sons ' + PL("william-tufts-1802", "William") + ' and ' + PL("edward-tufts-1806", "Edward") + ' later owned the Tufts saw and grist mills on the Medford Turnpike; see <a href="{P}businesses.html#medford-turnpike-mill">Businesses</a>.</p>'),
  service='<p>No military service has yet been matched to him. Note: Pending further work.</p>',
  family=('<p>Father: ' + PL(_NC, "Nathan Tufts, cordwainer, of Medford") + '. Mother: Mary Adams (Adams genealogy, p. 974). Brothers: Daniel Tufts, brick-maker, and ' + PL("nathan-tufts-1764", "Nathan Tufts (c. 1764&ndash;1835)") + '. Children on this site: ' + PL("william-tufts-1802", "William Tufts (1802&ndash;1862)") + ' and ' + PL("edward-tufts-1806", "Edward Tufts (1806&ndash;1875)") + '; grandsons ' + PL("george-f-tufts-1825", "George F.") + ' and ' + PL("alfred-tufts-1829", "Alfred Tufts") + '. Other children named by Sawyer: Joseph F. Tufts (eldest son) and a daughter who married Eliab P. Mackintire.</p>'),
  unverified='<strong>Birth date:</strong> about 1762, inferred from his age at death; no birth record cited. <strong>Wife:</strong> not named by Sawyer. Note: Pending further work.'))
SP[_AM] = "<ul><li>Not named in the sources checked (Sawyer, <em>Old Charlestown</em>). Note: Pending further work.</li></ul>"
NEWUNCHK.add(_AM)
REL[_AM] = [(_NC, "father Nathan Tufts, cordwainer"), ("nathan-tufts-1764", "brother Nathan Tufts (c. 1764&ndash;1835)"), ("william-tufts-1802", "son William Tufts"), ("edward-tufts-1806", "son Edward Tufts"), ("george-f-tufts-1825", "grandson George F. Tufts"), ("alfred-tufts-1829", "grandson Alfred Tufts")]
for _s, _r in [("nathan-tufts-1764", [(_NC, "father Nathan Tufts, cordwainer"), (_AM, "brother Deacon Amos Tufts")]), ("william-tufts-1802", [(_AM, "father Deacon Amos Tufts")]), ("edward-tufts-1806", [(_AM, "father Deacon Amos Tufts")]), ("george-f-tufts-1825", [(_AM, "grandfather Deacon Amos Tufts")]), ("alfred-tufts-1829", [(_AM, "grandfather Deacon Amos Tufts")]), ("nathan-tufts-15-7", [(_NC, "possibly the same man: Nathan Tufts, cordwainer")]), ("daniel-tufts", [(_NC, "possible father: Nathan Tufts, cordwainer (not established)")])]:
    REL.setdefault(_s, []); REL[_s] = REL[_s] + _r
TURNPIKE_MILL = ('<section id="medford-turnpike-mill"><h2>Tufts Mills on the Medford Turnpike</h2>'
  + '<p><strong>Tufts association:</strong> A tide-powered mill site on the marsh between the Mystic River and the Medford Turnpike, at the point called &ldquo;the Rock,&rdquo; where a Nathan Tufts built a new mill in 1834 and where ' + PL("william-tufts-1802", "William Tufts") + ' and ' + PL("edward-tufts-1806", "Edward Tufts") + ', sons of ' + PL(_AM, "Deacon Amos Tufts") + ', were among the owners of &ldquo;the saw and grist mills on the turnpike&rdquo; in 1848.</p>'
  + FIG("gershom-cutter-house-medford-turnpike.jpg", "hfig-flow")
  + Q("It appears by record of January 4, 1834, that Nathan Tufts asked for leave to open a cut through the road, fifteen feet wide, to carry his new mill near the &ldquo;Rock,&rdquo; so called. This indicates that there had been at least one prior to that date.", _M20)
  + '<p>The turnpike had become, in the Register&rsquo;s words, &ldquo;though never so called, a milldam road,&rdquo; once sluices let the tide flood the marsh behind it. In 1848 the turnpike agent was told to confer &ldquo;with the Messrs. Tufts&rdquo; about a neglected culvert. The resulting three-party agreement named as owners of the mills William Tufts, Edward Tufts and Gershom Cutter; William, Edward and Joseph F. Tufts also owned the neighbouring farm land (p. 20).</p>'
  + Q("Gershom Cutter, in 1845, purchased the Tufts mill on the Medford Turnpike, rebuilt that structure which had been destroyed by fire and which was again burnt while in his charge. He was mainly engaged in sawing of mahogany.", "William R. Cutter, <em>Medford Historical Register</em>, vol. III, p. 130, as quoted in " + _M20)
  + '<p>The Register concludes that &ldquo;at least four successive mills stood on that spot&rdquo; and that the later ones were probably saw mills only (p. 21).</p>'
  + UNV("Which Nathan Tufts asked for the 1834 cut is not stated. The likeliest is " + PL("nathan-tufts-1764", "Nathan Tufts of Charlestown (c. 1764&ndash;1835)") + ", the mill owner whose Medford lands passed to his nephews William and Edward, but this is not confirmed. The exact location of the Rock and the dates of the fires are also not established. Note: Pending further work.")
  + '</section>')
_EXTRA_1113 = EXTRA
def EXTRA(path):
    out = _EXTRA_1113(path)
    if path in ("profiles/nathan-tufts-1764.html", "profiles/william-tufts-1802.html", "profiles/edward-tufts-1806.html"):
        out += '{DIV}<section id="turnpike-mill"><h2>Mill on the Medford Turnpike</h2><p>' + ("A Nathan Tufts, probably this man, asked in January 1834 for leave to cut through the Medford Turnpike to serve his new tide mill near &ldquo;the Rock&rdquo; (" if "nathan" in path else "In 1848 he was one of the owners of &ldquo;the saw and grist mills on the turnpike&rdquo; at Medford, with his brother and Gershom Cutter (") + _M20 + '). See <a href="{P}businesses.html#medford-turnpike-mill">Businesses: Tufts Mills on the Medford Turnpike</a>.</p></section>'
    if path == "profiles/nathan-tufts-15-7.html":
        out += '{DIV}<p>Sawyer&rsquo;s <em>Old Charlestown</em> (p. 162) describes a Nathan Tufts of Medford, cordwainer and farmer, son of Peter of Milk Row; whether he is this man is not established. See ' + PL(_NC, "Nathan Tufts, cordwainer") + '.</p>'
    if path == "profiles/daniel-tufts.html":
        out += '{DIV}<p>Sawyer (<em>Old Charlestown</em>, p. 162) names a Daniel Tufts, brick-maker and farmer living outside Charlestown Neck and a legislator in 1811&ndash;12, as a son of ' + PL(_NC, "Nathan Tufts, cordwainer") + '. Whether he is this Daniel is not established. Note: Pending further work.</p>'
    return out
if "BIZ_HTML" in globals() and "medford-turnpike-mill" not in BIZ_HTML:
    BIZ_HTML = BIZ_HTML + "{DIV}" + TURNPIKE_MILL
    page("businesses.html", "Businesses | Tufts Lineage &amp; Legacy", "Places", "Businesses", "The trades of the Tufts family, colonial era to the 19th century", BIZ_HTML)
